code.source:
CREATE TABLE Dept (dept VARCHAR(10) PRIMARY KEY, floor INT);
CREATE TABLE Employee (
  emp_id INT PRIMARY KEY,
  name   VARCHAR(20) NOT NULL,
  dept   VARCHAR(10),
  salary INT CHECK (salary > 0),
  city   VARCHAR(20)
);
INSERT INTO Dept VALUES ('IT', 3), ('HR', 1), ('Admin', 2);
INSERT INTO Employee VALUES
 (1, 'Asha',  'IT',    60000, 'Delhi'),
 (2, 'Ravi',  'HR',    45000, 'Noida'),
 (3, 'Meena', 'IT',    75000, 'Delhi'),
 (4, 'John',  'Sales', 40000, 'Gurugram'),
 (5, 'Kiran', 'Sales', 52000, 'Delhi'),
 (6, 'Farah', 'HR',    48000, NULL);

SELECT dept, SUM(salary) AS total
FROM Employee
GROUP BY dept
HAVING SUM(salary) > 92000
ORDER BY total DESC;

SELECT COUNT(*), COUNT(city), COUNT(DISTINCT city) FROM Employee;

SELECT name FROM Employee WHERE name LIKE '_a%' ORDER BY name;

SELECT e.name, d.floor
FROM Employee e JOIN Dept d ON e.dept = d.dept
WHERE e.salary > 50000 ORDER BY e.name;

SELECT name FROM Employee
WHERE salary > (SELECT AVG(salary) FROM Employee) ORDER BY name;

SELECT name FROM Employee WHERE city <> 'Delhi' ORDER BY name;

workedExamples.problem:
Using the Employee table from the notes (6 rows; Farah's city is NULL; Kiran is in Sales, which has no row in Dept), find the output of:
(a) SELECT COUNT(*) FROM Employee WHERE salary BETWEEN 45000 AND 52000;
(b) SELECT e.name, d.floor FROM Employee e LEFT JOIN Dept d ON e.dept = d.dept WHERE e.salary > 50000;
(c) SELECT MAX(salary) FROM Employee WHERE salary < (SELECT MAX(salary) FROM Employee);
